                    assert_eq!(BORROW_BYTES, 49);
                    assert_eq!(removed.1, 48);
                    assert_eq!(removed.2, 48);
                    assert_eq!(new.2, old.2 + 1);
                    assert_eq!(old.5, new.5 + 48);
                }
            }
            _ => unreachable!(),
        _ => {}

